fn xs_next(mut x: u64) -> u64 { x ^= x << 13; x ^= x >> 7; x ^= x << 17; x }
fn main(){ let mut text=String::new(); let mut seed:u64=12345; for _ in 0..100 { let mut r=xs_next(seed); fn gen(depth:u64, r:u64, text:&mut String)->u64{ let mut rr=r; if depth==0||rr%4==0 { if ((rr>>8)%2)==0 { let n=3+(rr%12); for _ in 0..n { rr=xs_next(rr); text.push((b'a'+(rr%26) as u8) as char); } } else { text.push_str(&((rr>>16)%100000).to_string()); } text.push(' '); return rr; } text.push('('); let kids=2+((rr>>24)%4); for _ in 0..kids { rr=gen(depth-1,rr,text); } text.push(')'); text.push(' '); rr } seed=gen(4,r,&mut text); } let mut h:u64=1469598103934665603; for b in text.as_bytes(){ h=(h^(*b as u64))*1099511628211; } println!("{}",text.len()); println!("{}",h); }